update fin_stock_init_batch
set status = #{toStatus},
    version = version + 1,
    submitted_by = #{submittedBy}, submitted_time = sysdate(),
    approved_by = #{approvedBy}, approved_time = sysdate(),
    posted_by = #{postedBy}, posted_time = sysdate(),
    post_idempotency_key = #{postIdempotencyKey},
    update_by = #{updateBy},
    update_time = sysdate()
where tenant_id = #{tenantId}
  and batch_id = #{batchId}
  and status = #{fromStatus}
  and version = #{version}

