set status = 'DELETED', update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where tenant_id = #{tenantId} and batch_id = #{batchId}
  and status in ('DRAFT', 'VALIDATED', 'SUBMITTED', 'APPROVED')
  and version = #{version}

